files.tasks/migrate.yml:
- name: Run migrations for {{ app_name }}
  ansible.builtin.command:
    cmd: ./manage.py migrate --database {{ db_name }}
    chdir: "{{ app_root }}/current"
  run_once: true

files.roles/common/defaults/main.yml:
common_timezone: UTC
common_users:
  - { name: alice, groups: [sudo] }
  - { name: bob, groups: [] }

files.roles/nginx/templates/nginx.conf.j2:
# {{ ansible_managed | default('Managed by Ansible') }}
user {{ nginx_user }};
worker_processes {{ nginx_worker_processes }};

http {
    keepalive_timeout {{ nginx_keepalive }};
    upstream {{ app_name }} {
{% for u in upstreams %}
        server {{ u }}:{{ listen_port }};
{% endfor %}
    }
    server {
        listen {{ listen_port }};
        server_name {{ nginx_server_name }};
        root {{ app_root }}/current/public;
    }
}
